() => {
  const now = new Date().toLocaleTimeString('zh-CN', { hour12: false });
  const hasBadge = document.body.innerText.includes('检测到数据变化');
  const titleEl = document.querySelector('h1');
  return { time: now, hasBadge, h1: titleEl ? titleEl.textContent : null };
}

async () => {
  const deadline = Date.now() + 60000;
  while (Date.now() < deadline) {
    const text = document.body.innerText;
    if (text.includes('检测到数据变化')) {
      const idx = text.indexOf('检测到数据变化');
      return { found: true, at: new Date().toLocaleTimeString('zh-CN', { hour12: false }), snippet: text.slice(Math.max(0, idx - 50), idx + 120) };
    }
    await new Promise(r => setTimeout(r, 2000));
  }
  return { found: false, at: new Date().toLocaleTimeString('zh-CN', { hour12: false }) };
}

() => {
  window.__badgeWatch = window.__badgeWatch || { foundAt: null, text: null };
  if (!window.__badgeObserver) {
    window.__badgeObserver = new MutationObserver(() => {
      if (window.__badgeWatch.foundAt) return;
      const txt = document.body.innerText;
      if (txt.includes('检测到数据变化')) {
        const idx = txt.indexOf('检测到数据变化');
        window.__badgeWatch.foundAt = new Date().toLocaleTimeString('zh-CN', { hour12: false });
        window.__badgeWatch.text = txt.slice(Math.max(0, idx - 60), idx + 140).replace(/\s+/g, ' ');
      }
    });
    window.__badgeObserver.observe(document.body, { childList: true, subtree: true, characterData: true });
  }
  return { installed: true, watch: window.__badgeWatch, now: new Date().toLocaleTimeString('zh-CN', { hour12: false }) };
}

