() => {
  window.scrollTo(0, 0);
  const txt = document.body.innerText;
  const gi = txt.indexOf('已自动重新生成报表');
  const summaryIdx = txt.indexOf('本报表基于');
  const anomalyIdx = txt.indexOf('监测到');
  return {
    greenBadge: txt.slice(gi - 20, gi + 80).replace(/\s+/g, ' '),
    summaryLine: summaryIdx >= 0 ? txt.slice(summaryIdx, summaryIdx + 40).replace(/\s+/g, ' ') : null,
    anomalyLine: anomalyIdx >= 0 ? txt.slice(anomalyIdx, anomalyIdx + 30).replace(/\s+/g, ' ') : null,
    dateNearTitle: (txt.match(/AI 高管决策简报\s*[\s\S]{0,20}/) || [''])[0].replace(/\s+/g, ' ')
  };
}

() => {
