() => {
  const txt = document.body.innerText;
  const ti = txt.indexOf('综合经营分析——投放金额前5机构核心指标专题');
  return { afterTitle: ti >= 0 ? txt.slice(ti, ti + 500).replace(/\s+/g, ' ') : null };
