() => {
  const els = [...document.querySelectorAll('*')];
  const target = els.find(e => e.children.length === 0 && e.textContent.includes('AI 高管决策简报'));
  if (target) {
    const rect = target.getBoundingClientRect();
    window.scrollBy(0, rect.top - 80);
  }
  return { scrolled: !!target };
}

() => {
  const els = [...document.querySelectorAll('*')];
  const scrollers = els.filter(e => e.scrollHeight > e.clientHeight + 50 && /(auto|scroll)/.test(getComputedStyle(e).overflowY));
  scrollers.forEach(e => e.scrollTo({ top: 0 }));
  window.scrollTo(0, 0);
  const badge = els.find(e => e.children.length === 0 && e.textContent.includes('已自动重新生成报表'));
  if (badge) badge.scrollIntoView({ block: 'center' });
  return { scrollers: scrollers.map(e => e.tagName + '.' + (e.className || '').toString().slice(0, 40)) };
}
